#!/usr/bin/env python3
"""Persistent broadcast-state recordings for the PuddleDuck web console.

A recording is a small SQLite database with immutable metadata and the compact
JSON state packets read from ``/dev/puddleduck_ops``.  Writing happens on a
background thread so filesystem latency never delays the state loop.  The
format intentionally stores the original state packet: future viewers can use
telemetry fields that older policies did not consume (temperatures, BMS cells,
new sensors, and so on) without changing the recorder schema.
"""

from __future__ import annotations

import datetime as _datetime
import json
import os
import queue
import re
import sqlite3
import threading
import time
import zlib
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple

RECORDING_SCHEMA = 1
RECORDING_SUFFIX = ".pdrec"
DEFAULT_RECORDING_ROOT = "~/recordings"
MAX_SAMPLE_LIMIT = 5000
_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,191}\.pdrec$")


def _safe_component(value: Any, fallback: str = "policy") -> str:
    text = str(value or "").strip()
    text = re.sub(r"[^A-Za-z0-9._-]+", "-", text).strip("-._")
    return (text or fallback)[:96]


def _json_value(value: Any) -> str:
    return json.dumps(value, separators=(",", ":"), ensure_ascii=False)


def _parse_json_value(value: str) -> Any:
    try:
        return json.loads(value)
    except Exception:
        return value


def _viewer_state(state: Any) -> Dict[str, Any]:
    """Return the telemetry subset needed by the browser replay UI.

    The downloaded SQLite file retains every original key.  Avoid sending
    controller event payloads and unrelated debug fields thousands of times
    when the browser asks for an overview or playback window.
    """
    if not isinstance(state, dict):
        return {}
    keys = ("robot", "options", "time", "policy", "motors", "sensors", "osc")
    return {key: state[key] for key in keys if key in state}


class _RecordingWriter:
    """One background SQLite writer for one automatic or manual recording."""

    def __init__(
        self,
        root: Path,
        first_state: Dict[str, Any],
        *,
        queue_size: int = 10000,
        source: str = "policy",
        label: Optional[str] = None,
    ):
        self.root = root
        self.root.mkdir(parents=True, exist_ok=True)
        self.started_wall_ms = int(time.time() * 1000)
        self.started_mono = time.monotonic()
        self.source = "manual" if str(source).strip().lower() == "manual" else "policy"
        current_policy = str((first_state.get("policy") or {}).get("name") or "").strip()
        self.policy_name = current_policy if current_policy else ("policy" if self.source == "policy" else "")
        self.robot_name = str(first_state.get("robot") or "")
        self.options = str(first_state.get("options") or "")
        stamp = _datetime.datetime.fromtimestamp(
            self.started_wall_ms / 1000.0, tz=_datetime.timezone.utc
        ).strftime("%Y%m%dT%H%M%SZ")
        file_label = str(label or self.policy_name or self.source).strip()
        base = f"{stamp}_{_safe_component(file_label, self.source)}"
        path = self.root / f"{base}{RECORDING_SUFFIX}"
        serial = 2
        while path.exists():
            path = self.root / f"{base}-{serial}{RECORDING_SUFFIX}"
            serial += 1
        self.path = path
        self._queue: queue.Queue = queue.Queue(maxsize=max(128, int(queue_size)))
        self._stop = object()
        self._dropped = 0
        self._sample_count = 0
        self._last_elapsed_ms = 0
        self._last_wall_ms = self.started_wall_ms
        self._error = ""
        self._closed = threading.Event()
        self._thread = threading.Thread(
            target=self._run,
            name=f"recording-{path.stem[:32]}",
            daemon=True,
        )
        self._thread.start()

    @property
    def dropped(self) -> int:
        return int(self._dropped)

    @property
    def error(self) -> str:
        return self._error

    @property
    def sample_count(self) -> int:
        return int(self._sample_count)

    @property
    def elapsed_ms(self) -> int:
        return int(self._last_elapsed_ms)

    def snapshot(self) -> Dict[str, Any]:
        return {
            "name": self.path.name,
            "path": str(self.path),
            "policy": self.policy_name,
            "source": self.source,
            "robot": self.robot_name,
            "options": self.options,
            "started_ms": self.started_wall_ms,
            "duration_ms": self.elapsed_ms,
            "sample_count": self.sample_count,
            "dropped_samples": self.dropped,
            "active": not self._closed.is_set(),
            "error": self.error,
        }

    def append(self, state: Dict[str, Any], wall_ms: Optional[int] = None) -> bool:
        if self._closed.is_set():
            return False
        wall = int(wall_ms if wall_ms is not None else time.time() * 1000)
        elapsed = max(0, wall - self.started_wall_ms)
        try:
            payload = json.dumps(state, separators=(",", ":"), ensure_ascii=False)
        except Exception:
            payload = json.dumps(dict(state or {}), separators=(",", ":"), default=str)
        try:
            self._queue.put_nowait((elapsed, wall, payload))
            return True
        except queue.Full:
            self._dropped += 1
            return False

    def close(self, timeout: float = 10.0) -> None:
        if self._closed.is_set():
            return
        try:
            self._queue.put(self._stop, timeout=1.0)
        except queue.Full:
            # Make room for the sentinel without blocking the serial loop.
            try:
                self._queue.get_nowait()
                self._dropped += 1
            except queue.Empty:
                pass
            try:
                self._queue.put_nowait(self._stop)
            except queue.Full:
                pass
        self._thread.join(timeout=max(0.1, float(timeout)))

    def _write_meta(self, db: sqlite3.Connection, values: Dict[str, Any]) -> None:
        db.executemany(
            "INSERT OR REPLACE INTO metadata(key,value) VALUES(?,?)",
            [(str(key), _json_value(value)) for key, value in values.items()],
        )

    def _run(self) -> None:
        db: Optional[sqlite3.Connection] = None
        try:
            db = sqlite3.connect(str(self.path), timeout=10.0)
            db.execute("PRAGMA synchronous=NORMAL")
            db.execute("PRAGMA temp_store=MEMORY")
            db.execute(
                "CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL)"
            )
            db.execute(
                "CREATE TABLE samples("
                "seq INTEGER PRIMARY KEY AUTOINCREMENT,"
                "elapsed_ms INTEGER NOT NULL,"
                "wall_ms INTEGER NOT NULL,"
                "payload BLOB NOT NULL)"
            )
            db.execute("CREATE INDEX samples_elapsed_idx ON samples(elapsed_ms)")
            self._write_meta(
                db,
                {
                    "schema": RECORDING_SCHEMA,
                    "format": "puddleduck-state-sqlite",
                    "payload_encoding": "json-zlib-1",
                    "policy": self.policy_name,
                    "source": self.source,
                    "robot": self.robot_name,
                    "options": self.options,
                    "started_ms": self.started_wall_ms,
                    "active": True,
                },
            )
            db.commit()

            pending: List[Tuple[int, int, str]] = []
            next_commit = time.monotonic() + 0.5
            stopping = False
            while not stopping:
                timeout = max(0.02, next_commit - time.monotonic())
                try:
                    item = self._queue.get(timeout=timeout)
                except queue.Empty:
                    item = None
                if item is self._stop:
                    stopping = True
                elif item is not None:
                    pending.append(item)

                now = time.monotonic()
                if pending and (len(pending) >= 100 or now >= next_commit or stopping):
                    encoded = [
                        (elapsed, wall, sqlite3.Binary(zlib.compress(payload.encode("utf-8"), 1)))
                        for elapsed, wall, payload in pending
                    ]
                    db.executemany(
                        "INSERT INTO samples(elapsed_ms,wall_ms,payload) VALUES(?,?,?)",
                        encoded,
                    )
                    self._sample_count += len(pending)
                    self._last_elapsed_ms = int(pending[-1][0])
                    self._last_wall_ms = int(pending[-1][1])
                    pending.clear()
                    db.commit()
                    next_commit = now + 0.5

            # Drain anything enqueued just before the sentinel became visible.
            while True:
                try:
                    item = self._queue.get_nowait()
                except queue.Empty:
                    break
                if item is self._stop:
                    continue
                pending.append(item)
            if pending:
                encoded = [
                    (elapsed, wall, sqlite3.Binary(zlib.compress(payload.encode("utf-8"), 1)))
                    for elapsed, wall, payload in pending
                ]
                db.executemany(
                    "INSERT INTO samples(elapsed_ms,wall_ms,payload) VALUES(?,?,?)",
                    encoded,
                )
                self._sample_count += len(pending)
                self._last_elapsed_ms = int(pending[-1][0])
                self._last_wall_ms = int(pending[-1][1])
                pending.clear()

            self._write_meta(
                db,
                {
                    "active": False,
                    "ended_ms": self._last_wall_ms,
                    "duration_ms": self._last_elapsed_ms,
                    "sample_count": self._sample_count,
                    "dropped_samples": self._dropped,
                },
            )
            db.commit()
        except Exception as exc:  # pragma: no cover - exercised through status
            self._error = f"{type(exc).__name__}: {exc}"
            try:
                if db is not None:
                    self._write_meta(
                        db,
                        {
                            "active": False,
                            "error": self._error,
                            "duration_ms": self._last_elapsed_ms,
                            "sample_count": self._sample_count,
                            "dropped_samples": self._dropped,
                        },
                    )
                    db.commit()
            except Exception:
                pass
        finally:
            try:
                if db is not None:
                    db.close()
            finally:
                self._closed.set()


class PuddleDuckRecordingStore:
    """Auto-recorder plus read-only web-library operations."""

    def __init__(self, root: Optional[str] = None, *, stop_grace_s: float = 1.0):
        configured = root or os.environ.get("PUDDLEDUCK_RECORDINGS_DIR") or DEFAULT_RECORDING_ROOT
        self.root = Path(configured).expanduser().resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        self.stop_grace_s = max(0.0, float(stop_grace_s))
        self._lock = threading.RLock()
        self._active: Optional[_RecordingWriter] = None
        self._finishing: set[_RecordingWriter] = set()
        self._last_policy_mono = 0.0
        self._last_error = ""
        self._latest_state: Optional[Dict[str, Any]] = None
        self._repair_stale_recordings()

    def _repair_stale_recordings(self) -> None:
        """Finalize files left active by power loss or process termination."""
        for path in self.root.glob(f"*{RECORDING_SUFFIX}"):
            if path.is_symlink() or not path.is_file():
                continue
            db = None
            try:
                db = sqlite3.connect(str(path), timeout=2.0)
                row = db.execute(
                    "SELECT value FROM metadata WHERE key='active'"
                ).fetchone()
                if row is None or not bool(_parse_json_value(str(row[0]))):
                    continue
                stats = db.execute(
                    "SELECT COUNT(*),COALESCE(MAX(elapsed_ms),0),COALESCE(MAX(wall_ms),0) FROM samples"
                ).fetchone()
                values = {
                    "active": False,
                    "interrupted": True,
                    "ended_ms": int(stats[2] or 0),
                    "duration_ms": int(stats[1] or 0),
                    "sample_count": int(stats[0] or 0),
                    "error": "recording process ended before finalization",
                }
                db.executemany(
                    "INSERT OR REPLACE INTO metadata(key,value) VALUES(?,?)",
                    [(key, _json_value(value)) for key, value in values.items()],
                )
                db.commit()
            except Exception:
                continue
            finally:
                if db is not None:
                    db.close()

    def _start_writer_locked(
        self,
        state: Dict[str, Any],
        *,
        source: str,
        label: Optional[str] = None,
    ) -> _RecordingWriter:
        writer = _RecordingWriter(self.root, state, source=source, label=label)
        self._active = writer
        self._last_error = ""
        return writer

    def _finish_async(self, writer: Optional[_RecordingWriter]) -> None:
        if writer is None:
            return
        with self._lock:
            self._finishing.add(writer)
        threading.Thread(target=self._finish, args=(writer,), daemon=True).start()

    def observe(self, state: Dict[str, Any]) -> None:
        """Record a state packet and manage policy-run boundaries.

        A manual recording owns the recorder until the operator stops it.  In
        that mode policy start/stop transitions are simply part of the same
        recording.  Otherwise RLWalk policy names automatically delimit files.
        """
        now_mono = time.monotonic()
        wall_ms = int(time.time() * 1000)
        policy = state.get("policy") if isinstance(state, dict) else None
        policy_name = str(policy.get("name") or "").strip() if isinstance(policy, dict) else ""
        old: Optional[_RecordingWriter] = None
        with self._lock:
            self._latest_state = dict(state or {})
            active = self._active
            if active is not None and active.source == "manual":
                active.append(state, wall_ms)
                return

            if policy_name:
                self._last_policy_mono = now_mono
                if active is None or active.policy_name != policy_name:
                    old = active
                    try:
                        active = self._start_writer_locked(
                            state, source="policy", label=policy_name
                        )
                        print(
                            f"[recordings] started {active.path.name} policy={policy_name}",
                            flush=True,
                        )
                    except Exception as exc:
                        self._active = None
                        self._last_error = f"{type(exc).__name__}: {exc}"
                        print(f"[recordings] unable to start: {self._last_error}", flush=True)
                        active = None
                if active is not None:
                    active.append(state, wall_ms)
            elif active is not None:
                # Keep a short post-policy tail so the viewer includes the final
                # relaxed state and policy-stop transition.
                active.append(state, wall_ms)
                if now_mono - self._last_policy_mono >= self.stop_grace_s:
                    self._active = None
                    old = active

        self._finish_async(old)

    def status(self) -> Dict[str, Any]:
        with self._lock:
            active = self._active.snapshot() if self._active is not None else None
            has_state = self._latest_state is not None
        source = str((active or {}).get("source") or "")
        return {
            "ok": True,
            "active": bool(active),
            "source": source,
            "recording": active,
            "can_start": active is None and has_state,
            "can_stop": bool(active and source == "manual"),
            "message": self._last_error,
        }

    def telemetry_status(self) -> Dict[str, Any]:
        status = self.status()
        recording = status.get("recording") or {}
        return {
            "active": bool(status.get("active")),
            "source": str(status.get("source") or ""),
            "name": str(recording.get("name") or ""),
            "started_ms": int(recording.get("started_ms") or 0),
            "duration_ms": int(recording.get("duration_ms") or 0),
            "sample_count": int(recording.get("sample_count") or 0),
            "dropped_samples": int(recording.get("dropped_samples") or 0),
            "can_start": bool(status.get("can_start")),
            "can_stop": bool(status.get("can_stop")),
        }

    def start_manual(self) -> Dict[str, Any]:
        with self._lock:
            active = self._active
            if active is not None:
                if active.source == "manual":
                    result = self.status()
                    result["message"] = "manual recording is already active"
                    return result
                raise RuntimeError(
                    "an automatic RLWalk recording is active; stop the policy before starting a manual recording"
                )
            if self._latest_state is None:
                raise RuntimeError("no live robot state is available yet")
            first_state = dict(self._latest_state)
            try:
                writer = self._start_writer_locked(
                    first_state, source="manual", label="manual"
                )
                writer.append(first_state, int(time.time() * 1000))
            except Exception as exc:
                self._active = None
                self._last_error = f"{type(exc).__name__}: {exc}"
                raise RuntimeError(self._last_error) from exc
        print(f"[recordings] manual start {writer.path.name}", flush=True)
        result = self.status()
        result["message"] = f"recording {writer.path.name}"
        return result

    def stop_manual(self) -> Dict[str, Any]:
        with self._lock:
            writer = self._active
            if writer is None:
                result = self.status()
                result["message"] = "no manual recording is active"
                return result
            if writer.source != "manual":
                raise RuntimeError(
                    "the active RLWalk recording stops automatically when the policy stops"
                )
            self._active = None
        self._finish_async(writer)
        print(f"[recordings] manual stop {writer.path.name}", flush=True)
        result = self.status()
        result["message"] = f"stopped {writer.path.name}"
        result["stopping"] = writer.snapshot()
        return result

    def _finish(self, writer: _RecordingWriter) -> None:
        try:
            writer.close()
            if writer.error:
                self._last_error = writer.error
                print(f"[recordings] {writer.path.name} failed: {writer.error}", flush=True)
            else:
                print(
                    f"[recordings] saved {writer.path.name} samples={writer.sample_count} "
                    f"duration_ms={writer.elapsed_ms} dropped={writer.dropped}",
                    flush=True,
                )
        finally:
            with self._lock:
                self._finishing.discard(writer)

    def close(self) -> None:
        with self._lock:
            active = self._active
            self._active = None
            finishing = list(self._finishing)
        if active is not None:
            self._finish(active)
        # Policy changes finish writers asynchronously so the serial loop never
        # blocks on SQLite.  Process shutdown must still wait for those writers
        # before the filesystem or test temporary directory disappears.
        for writer in finishing:
            writer.close()
        deadline = time.monotonic() + 10.0
        while time.monotonic() < deadline:
            with self._lock:
                if not self._finishing:
                    break
            time.sleep(0.01)

    def _clean_name(self, name: Any) -> str:
        clean = str(name or "").strip()
        if not _NAME_RE.fullmatch(clean):
            raise ValueError("invalid recording filename")
        return clean

    def _path(self, name: Any) -> Path:
        clean = self._clean_name(name)
        path = (self.root / clean).resolve()
        if path.parent != self.root:
            raise ValueError("invalid recording path")
        return path

    @staticmethod
    def _connect_readonly(path: Path) -> sqlite3.Connection:
        db = sqlite3.connect(f"file:{path}?mode=ro", uri=True, timeout=5.0)
        db.row_factory = sqlite3.Row
        return db

    def _read_metadata(self, path: Path) -> Dict[str, Any]:
        db = self._connect_readonly(path)
        try:
            rows = db.execute("SELECT key,value FROM metadata").fetchall()
            meta = {str(row["key"]): _parse_json_value(str(row["value"])) for row in rows}
            stats = db.execute(
                "SELECT COUNT(*) AS n, COALESCE(MAX(elapsed_ms),0) AS duration_ms, "
                "COALESCE(MIN(wall_ms),0) AS first_wall_ms, COALESCE(MAX(wall_ms),0) AS last_wall_ms "
                "FROM samples"
            ).fetchone()
            meta["sample_count"] = int(stats["n"] or meta.get("sample_count") or 0)
            meta["duration_ms"] = int(stats["duration_ms"] or meta.get("duration_ms") or 0)
            if not meta.get("started_ms") and stats["first_wall_ms"]:
                meta["started_ms"] = int(stats["first_wall_ms"])
            if not meta.get("ended_ms") and stats["last_wall_ms"]:
                meta["ended_ms"] = int(stats["last_wall_ms"])
            meta.setdefault("schema", RECORDING_SCHEMA)
            return meta
        finally:
            db.close()

    def _item(self, path: Path) -> Dict[str, Any]:
        meta = self._read_metadata(path)
        st = path.stat()
        name = path.name
        return {
            "name": name,
            "size_bytes": int(st.st_size),
            "modified_ms": int(st.st_mtime * 1000),
            "policy": str(meta.get("policy") or ""),
            "source": str(meta.get("source") or "policy"),
            "robot": str(meta.get("robot") or ""),
            "options": str(meta.get("options") or ""),
            "started_ms": int(meta.get("started_ms") or 0),
            "ended_ms": int(meta.get("ended_ms") or 0),
            "duration_ms": int(meta.get("duration_ms") or 0),
            "sample_count": int(meta.get("sample_count") or 0),
            "dropped_samples": int(meta.get("dropped_samples") or 0),
            "active": bool(meta.get("active", False)),
            "error": str(meta.get("error") or ""),
            "download_url": f"/api/recordings/{name}/download",
        }

    def list(self) -> Dict[str, Any]:
        with self._lock:
            active = self._active.snapshot() if self._active is not None else None
        items: List[Dict[str, Any]] = []
        for path in self.root.glob(f"*{RECORDING_SUFFIX}"):
            if path.is_symlink() or not path.is_file():
                continue
            try:
                item = self._item(path)
            except Exception as exc:
                # The file can be visible for a few milliseconds before the
                # background writer has created its metadata table.  Use the
                # in-memory active snapshot instead of surfacing a false error.
                if active and active.get("name") == path.name:
                    item = {
                        **active,
                        "size_bytes": int(path.stat().st_size),
                        "modified_ms": int(path.stat().st_mtime * 1000),
                        "download_url": f"/api/recordings/{path.name}/download",
                    }
                else:
                    item = {
                        "name": path.name,
                        "size_bytes": int(path.stat().st_size),
                        "modified_ms": int(path.stat().st_mtime * 1000),
                        "policy": "",
                        "robot": "",
                        "duration_ms": 0,
                        "sample_count": 0,
                        "active": False,
                        "error": f"{type(exc).__name__}: {exc}",
                        "download_url": f"/api/recordings/{path.name}/download",
                    }
            if active and active.get("name") == item.get("name"):
                item.update(active)
                item["active"] = True
                item.setdefault("download_url", f"/api/recordings/{path.name}/download")
            items.append(item)
        if active and not any(item.get("name") == active.get("name") for item in items):
            items.append({
                **active,
                "size_bytes": 0,
                "modified_ms": int(active.get("started_ms") or 0),
                "download_url": f"/api/recordings/{active['name']}/download",
            })
        items.sort(key=lambda item: (int(item.get("started_ms") or 0), item["name"]), reverse=True)
        return {
            "ok": True,
            "recordings_dir": str(self.root),
            "active": active,
            "control": self.status(),
            "message": self._last_error,
            "recordings": items,
        }

    def info(self, name: Any) -> Dict[str, Any]:
        path = self._path(name)
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(f"recording not found: {path.name}")
        return {"ok": True, "recording": self._item(path)}

    def samples(
        self,
        name: Any,
        *,
        start_ms: int = 0,
        limit: int = 2000,
        overview: bool = False,
    ) -> Dict[str, Any]:
        path = self._path(name)
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(f"recording not found: {path.name}")
        start_ms = max(0, int(start_ms))
        limit = max(1, min(MAX_SAMPLE_LIMIT, int(limit)))
        db = self._connect_readonly(path)
        try:
            meta = self._read_metadata(path)
            total = int(meta.get("sample_count") or 0)
            stride = max(1, (total + limit - 1) // limit) if overview else 1
            if overview:
                rows = db.execute(
                    "SELECT seq,elapsed_ms,wall_ms,payload FROM samples "
                    "WHERE ((seq - 1) % ?) = 0 ORDER BY seq LIMIT ?",
                    (stride, limit),
                ).fetchall()
                # Preserve the final state even when the stride does not land
                # exactly on it; playback metadata and overview graphs should
                # show the relaxed/end state of the run.
                if rows and total and int(rows[-1]["seq"]) < total:
                    final_row = db.execute(
                        "SELECT seq,elapsed_ms,wall_ms,payload FROM samples ORDER BY seq DESC LIMIT 1"
                    ).fetchone()
                    if final_row is not None:
                        rows = list(rows)
                        if len(rows) >= limit:
                            rows[-1] = final_row
                        else:
                            rows.append(final_row)
            else:
                rows = db.execute(
                    "SELECT seq,elapsed_ms,wall_ms,payload FROM samples "
                    "WHERE elapsed_ms >= ? ORDER BY elapsed_ms,seq LIMIT ?",
                    (start_ms, limit),
                ).fetchall()
            samples = []
            for row in rows:
                try:
                    raw_payload = row["payload"]
                    if isinstance(raw_payload, (bytes, bytearray, memoryview)):
                        raw_payload = zlib.decompress(bytes(raw_payload)).decode("utf-8")
                    payload = json.loads(raw_payload)
                except Exception:
                    payload = {"_recording_error": "invalid compressed JSON payload"}
                samples.append({
                    "seq": int(row["seq"]),
                    "t_ms": int(row["elapsed_ms"]),
                    "wall_ms": int(row["wall_ms"]),
                    "state": _viewer_state(payload),
                })
            last_ms = int(samples[-1]["t_ms"]) if samples else start_ms
            duration_ms = int(meta.get("duration_ms") or 0)
            has_more = bool(samples) and last_ms < duration_ms
            return {
                "ok": True,
                "recording": path.name,
                "duration_ms": duration_ms,
                "sample_count": total,
                "start_ms": start_ms,
                "last_ms": last_ms,
                "next_ms": last_ms + 1 if has_more else None,
                "has_more": has_more,
                "stride": stride,
                "samples": samples,
            }
        finally:
            db.close()

    def download_path(self, name: Any) -> Path:
        path = self._path(name)
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(f"recording not found: {path.name}")
        return path

    def delete(self, name: Any) -> Dict[str, Any]:
        path = self._path(name)
        with self._lock:
            if self._active is not None and self._active.path == path:
                raise RuntimeError("the active recording cannot be deleted")
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError(f"recording not found: {path.name}")
        path.unlink()
        return {"ok": True, "message": f"deleted {path.name}"}
